export function minimumCoveringWindow(text, target) {
    if (!target)
        return '';
    const need = new Map();
    for (const c of target)
        need.set(c, (need.get(c) || 0) + 1);
    let missing = target.length, left = 0, bestStart = 0, bestLen = Infinity;
    for (let right = 0; right < text.length; right++) {
        const c = text[right];
        if ((need.get(c) || 0) > 0)
            missing--;
        need.set(c, (need.get(c) || 0) - 1);
        while (missing === 0) {
            if (right - left + 1 < bestLen) {
                bestLen = right - left + 1;
                bestStart = left;
            }
            const out = text[left++];
            need.set(out, (need.get(out) || 0) + 1);
            if (need.get(out) > 0)
                missing++;
        }
    }
    return bestLen === Infinity ? '' : text.slice(bestStart, bestStart + bestLen);
}
